import { placeOrder } from "./order-service.ts";

const card = process.argv[2] ?? "ok";

try {
  console.log(JSON.stringify(placeOrder(card)));
} catch (error) {
  if (error instanceof Error && error.name === "PaymentDeclinedError") {
    const effects = (error as Error & { effects?: string[] }).effects ?? [];
    console.error(JSON.stringify({ effects, error: `${error.name}: ${error.message}` }));
    process.exitCode = 2;
  } else {
    throw error;
  }
}
